const shareChannel = `-- name: ShareChannel :one
INSERT INTO shared_channels (channel_id, connection_id) VALUES ($1, $2)
ON CONFLICT (channel_id, connection_id) DO UPDATE SET channel_id = excluded.channel_id
RETURNING channel_id, connection_id, remote_channel_id, status, created_at
`

type ShareChannelParams struct {
	ChannelID    pgtype.UUID `json:"channel_id"`
	ConnectionID pgtype.UUID `json:"connection_id"`
}

func (q *Queries) ShareChannel(ctx context.Context, arg ShareChannelParams) (SharedChannel, error) {
	row := q.db.QueryRow(ctx, shareChannel, arg.ChannelID, arg.ConnectionID)
	var i SharedChannel
	err := row.Scan(
		&i.ChannelID,
		&i.ConnectionID,
		&i.RemoteChannelID,
		&i.Status,
		&i.CreatedAt,
	)
	return i, err
}

