const upsertChannelOffer = `-- name: UpsertChannelOffer :one
INSERT INTO channel_offers (connection_id, remote_channel_id, name, topic)
VALUES ($1, $2, $3, $4)
ON CONFLICT (connection_id, remote_channel_id) DO UPDATE SET name = excluded.name, topic = excluded.topic
RETURNING id, connection_id, remote_channel_id, name, topic, created_at
`

type UpsertChannelOfferParams struct {
	ConnectionID    pgtype.UUID `json:"connection_id"`
	RemoteChannelID pgtype.UUID `json:"remote_channel_id"`
	Name            string      `json:"name"`
	Topic           string      `json:"topic"`
}

func (q *Queries) UpsertChannelOffer(ctx context.Context, arg UpsertChannelOfferParams) (ChannelOffer, error) {
	row := q.db.QueryRow(ctx, upsertChannelOffer,
		arg.ConnectionID,
		arg.RemoteChannelID,
		arg.Name,
		arg.Topic,
	)
	var i ChannelOffer
	err := row.Scan(
		&i.ID,
		&i.ConnectionID,
		&i.RemoteChannelID,
		&i.Name,
		&i.Topic,
		&i.CreatedAt,
	)
	return i, err
}

