const useFederationInvite = `-- name: UseFederationInvite :one
UPDATE federation_invites SET used_at = now()
WHERE token_hash = $1 AND used_at IS NULL AND expires_at > now()
RETURNING id, workspace_id, name, token_hash, secret, created_by, expires_at, used_at
`

// UseFederationInvite takes an unused, unexpired invitation (once).
func (q *Queries) UseFederationInvite(ctx context.Context, tokenHash []byte) (FederationInvite, error) {
	row := q.db.QueryRow(ctx, useFederationInvite, tokenHash)
	var i FederationInvite
	err := row.Scan(
		&i.ID,
		&i.WorkspaceID,
		&i.Name,
		&i.TokenHash,
		&i.Secret,
		&i.CreatedBy,
		&i.ExpiresAt,
		&i.UsedAt,
	)
	return i, err
}
